theorem algebra_triangle_heights_bound (x y z : ℝ) :
  let S := x + y + z;
  let A := |x^2 + 2*y*z + 2*S + 3|;
  let B := |y^2 + 2*z*x + 2*S + 3|;
  let C := |z^2 + 2*x*y + 2*S + 3|;
  0 < A → 0 < B → 0 < C →
  A + B > C → A + C > B → B + C > A →
  x*y + y*z + z*x + 2*S ≤ 1 := by sorry
